from produire import produire,paras,steps,table
from vasculaire import nimodipine
parts=[
('L’{hémorragie sous-arachnoïdienne} est un saignement dans les espaces entourant le cerveau. Une rupture anévrismale est une cause majeure de la forme spontanée. Une raideur cervicale peut accompagner ou suivre la céphalée.',paras('Cette leçon concerne surtout la forme spontanée suspectée devant une céphalée brutale. Les formes traumatiques et les saignements non anévrismaux ont des parcours spécifiques.', 'Le méningisme vient de l’irritation par le sang. Une douleur cervicale apparemment isolée ne permet pas d’écarter le diagnostic si le début ou les signes associés sont inquiétants.')),
('Le {contexte augmente la vigilance sans faire le diagnostic}. Hypertension, tabagisme et certains antécédents familiaux ou vasculaires peuvent orienter. L’absence de facteur connu ne protège pas d’une rupture.',paras('Le protocole HUG cite notamment effort, hypertension, cocaïne, antécédents familiaux et polykystose. Ces facteurs ne sont ni nécessaires ni suffisants.', 'Une céphalée inhabituelle survenant lors d’un effort ou d’un rapport sexuel demande une évaluation urgente. La qualifier d’emblée de bénigne expose à manquer une hémorragie.')),
('La {rupture expose à plusieurs temps de danger}. Le saignement initial peut altérer conscience et perfusion cérébrale. Récidive, hydrocéphalie et ischémie retardée menacent ensuite.',paras('L’occlusion de la circulation du liquide cérébrospinal peut produire une hydrocéphalie aiguë. Une baisse neurologique secondaire exige une recherche de cause, pas une attribution automatique au vasospasme.', 'Le traitement de l’anévrisme réduit le risque de nouveau saignement. La nimodipine et la surveillance poursuivent un autre objectif, notamment limiter les déficits ischémiques secondaires.')),
('Le {tri impose une filière d’urgence}. Une céphalée nouvelle en coup de tonnerre, avec ou sans raideur, doit être investiguée. Coma, déficit ou convulsion renforcent l’urgence.',paras('Appeler le 144 hors hôpital en cas de tableau évocateur, surtout avec altération neurologique. Stabiliser voies aériennes, respiration et circulation et obtenir une imagerie rapide.', 'Ne pas attendre l’apparition d’une raideur, ni l’échec d’un antalgique. Une amélioration spontanée ou après traitement n’exclut pas une hémorragie selon le protocole HUG.')),
('L’{anamnèse reconstruit précisément le début}. Demander l’heure, le délai jusqu’au maximum et l’activité en cours. Rechercher syncope, vomissements et symptômes neurologiques transitoires.',paras('NICE décrit le coup de tonnerre comme une douleur soudaine intense atteignant typiquement son maximum en une à cinq minutes. Le caractère inhabituel et la vitesse de montée comptent davantage qu’une simple note de douleur.', 'Noter anticoagulants, antiagrégants, substances vasoactives, traumatismes et antécédents d’anévrisme. Un épisode récent inhabituel ne doit pas être automatiquement assimilé à une migraine connue.')),
('L’{examen cherche la gravité sans retarder l’imagerie}. Évaluer conscience, pupilles, motricité, langage et constantes. La raideur méningée peut être absente initialement.',paras('Rechercher asymétrie pupillaire, déficit focal, convulsion et signes d’instabilité. Documenter l’état initial pour repérer toute détérioration.', 'Ne pas forcer la flexion cervicale. Un examen neurologique normal chez un patient conscient ne permet pas de classer une céphalée brutale comme bénigne.')),
('L’{approche syndromique garde plusieurs urgences ouvertes}. Le coup de tonnerre n’est pas spécifique de l’hémorragie. Une cause vasculaire ou infectieuse reste possible malgré un premier examen rassurant.',table(['Hypothèse','Point discriminant'],[['Hémorragie sous-arachnoïdienne.','Sang à l’imagerie ou bilan complémentaire approprié après scanner négatif.'],['Dissection artérielle.','Douleur cervicocéphalique, Horner ou ischémie ; imagerie artérielle adaptée.'],['Méningite.','Contexte infectieux ; prélèvements et traitement urgent sans attendre le calendrier propre à l’hémorragie.'],['Autres causes de coup de tonnerre.','Autre saignement, thrombose veineuse ou vasoconstriction cérébrale réversible selon contexte.']])) ,
('Le {diagnostic commence par le scanner cérébral sans contraste}. Sa performance dépend notamment du délai et de la qualité d’interprétation. Un résultat négatif n’a pas la même portée à toute heure.',paras('Selon NICE, un scanner réalisé dans les six heures, interprété et documenté par un radiologue, ne conduit pas à une ponction systématique s’il est négatif. Discuter les autres diagnostics et demander l’avis du senior ou du spécialiste.', 'Après six heures, un scanner négatif peut nécessiter une ponction lombaire. Un doute clinique persistant ou un examen techniquement insuffisant demande un avis spécialisé, sans transformer le seuil horaire en garantie absolue.')),
('Les {examens complémentaires recherchent sang et cause}. L’angiographie par scanner aide à identifier l’anévrisme. La ponction peut compléter une imagerie négative selon délai et contexte.',paras('NICE recommande d’attendre au moins douze heures après le début pour la ponction destinée à rechercher une hémorragie, avec bilirubine par spectrophotométrie. Ce délai ne doit jamais retarder le transfert ou le scanner, et ne s’applique pas à la ponction d’une méningite suspectée.', 'Après confirmation, l’angioscanner recherche la cause sans délai. Un anévrisme découvert n’est responsable que si le siège du sang est compatible ; sinon avis spécialisé. Une angiographie artérielle spécialisée peut être nécessaire si la cause reste non identifiée.')),
('L’{algorithme associe diagnostic urgent et protection cérébrale}. Une imagerie positive déclenche immédiatement l’équipe neurovasculaire. Une imagerie négative conduit à réévaluer sa portée.',steps('Stabiliser et documenter heure de début, conscience et déficit.', 'Scanner cérébral sans contraste urgent ; bilan artériel selon résultat et protocole local.', 'Si négatif, analyser délai, qualité et suspicion résiduelle ; organiser les examens complémentaires spécialisés.', 'Si hémorragie, transfert ou admission spécialisée et décision de sécurisation de l’anévrisme.', 'Surveiller récidive, hydrocéphalie, ischémie retardée et complications générales.')),
('La {prise en charge suisse relève d’un centre spécialisé}. Neurochirurgie et neuroradiologie interventionnelle évaluent la sécurisation de l’anévrisme. Le traitement médical et la surveillance restent indispensables.',paras('Le choix entre embolisation et chirurgie dépend de l’anatomie, de la situation clinique et de l’expertise. La pression artérielle est gérée en évitant l’hypotension et en tenant compte du risque de resaignement ; aucun objectif unique n’est prescrit ici.', '@@MEDICAMENTS@@', 'Une aggravation neurologique justifie un nouveau scanner en première intention. Une hydrocéphalie responsable de détérioration peut nécessiter un drainage du liquide cérébrospinal. L’ischémie retardée requiert une stratégie spécialisée, avec maintien de l’euvolémie ; ne pas appliquer une hypervolémie prophylactique systématique.')),
('La {réadaptation dépasse la récupération motrice}. Fatigue, mémoire, humeur et reprise professionnelle demandent un suivi. La prévention vasculaire et le contrôle de l’anévrisme sont individualisés.',paras('Organiser rééducation et évaluation cognitive selon les besoins. Une personne autonome peut conserver une fatigue ou des difficultés exécutives importantes.', 'Informer sur les signes de récidive imposant une consultation urgente. Contrôler tabac et hypertension ; discuter l’imagerie de suivi et un éventuel conseil familial avec l’équipe, sans dépistage indistinct de tous les proches.')),
('Le {point clé} est la vitesse d’installation de la céphalée. La disparition de la douleur ou l’absence de raideur ne suffit pas à rassurer. Le bilan négatif doit toujours être interprété selon son délai et sa qualité.',paras('Distinguer le scanner initial de la recherche de la cause. La ponction pour hémorragie et celle pour infection suivent des calendriers différents. La nimodipine ne remplace pas la sécurisation de l’anévrisme.'))]
quiz=[('La raideur est-elle obligatoire ?','Non.'),('Une amélioration sous antalgique exclut-elle le saignement ?','Non.'),('Quel élément temporel rechercher ?','Le délai jusqu’à l’intensité maximale et l’heure précise du début.'),('Un examen neurologique normal suffit-il ?','Non.'),('Quel examen initial recherche le sang ?','Le scanner cérébral sans contraste.'),('Un scanner négatif a-t-il toujours la même portée ?','Non, délai, qualité et contexte comptent.'),('La ponction est-elle systématique après un scanner précoce négatif bien interprété ?','Non selon NICE ; avis clinique et spécialisé restent nécessaires.'),('Quand rechercher la bilirubine par ponction selon NICE ?','Au moins douze heures après le début si cet examen est indiqué.'),('Faut-il attendre ces douze heures pour le scanner ?','Non.'),('Ce délai de ponction vaut-il pour une méningite ?','Non.'),('Un anévrisme découvert est-il nécessairement responsable ?','Non, vérifier la concordance avec le saignement.'),('La nimodipine ferme-t-elle l’anévrisme ?','Non.'),('Une baisse neurologique secondaire est-elle toujours un vasospasme ?','Non, rechercher notamment récidive et hydrocéphalie.'),('Une autonomie motrice exclut-elle les séquelles ?','Non, fatigue et troubles cognitifs peuvent persister.')]
produire(6,parts,quiz,(5,20,21),nimodipine)
